#!/usr/bin/env bash
set -e

report=/home/eval/data/report.txt

printf '%-8s %6s %10s\n' REGION UNITS REVENUE > "$report"

awk -F '\t' '
    NR == 1 { next }
    {
        region = $1
        units[region] += $3
        price_cents = int($4 * 100 + 0.5)
        revenue_cents[region] += $3 * price_cents
        total_units += $3
        total_revenue_cents += $3 * price_cents
    }
    END {
        for (region in units)
            regions[++count] = region

        for (i = 1; i <= count; i++) {
            for (j = i + 1; j <= count; j++) {
                a = regions[i]
                b = regions[j]
                if (revenue_cents[a] < revenue_cents[b] ||
                    (revenue_cents[a] == revenue_cents[b] && a > b)) {
                    regions[i] = b
                    regions[j] = a
                }
            }
        }

        for (i = 1; i <= count; i++) {
            region = regions[i]
            printf "%-8s %6d %10.2f\n", region, units[region], revenue_cents[region] / 100
        }
        printf "%s\n", "--------------------------"
        printf "%-8s %6d %10.2f\n", "TOTAL", total_units, total_revenue_cents / 100
    }
' /home/eval/data/sales.tsv >> "$report"
